+function worktreeGitDir(tree: string): string | undefined {
+  let pointer: string;
+  try {
+    pointer = fs.readFileSync(path.join(tree, ".git"), "utf-8");
+  } catch {
+    return undefined; // a directory (plain checkout) or no repo at all
+  }
