diff --git a/apps/core/src/autonomous/report.test.ts b/apps/core/src/autonomous/report.test.ts
new file mode 100644
index 00000000..a56e23a4
--- /dev/null
+++ b/apps/core/src/autonomous/report.test.ts
@@ -0,0 +1,211 @@
+// =============================================================================
+// The morning report — spec 2026-09-28-overnight-runs.md §4.10, §7.
+//
+// The report is what a night is FOR: nobody watched it happen, so this file is
+// the only account of it. These tests are mostly about order and omission.
+// =============================================================================
+
+import test from "node:test";
+import assert from "node:assert/strict";
+import { duration, renderReport, type ReportInput } from "./report.js";
+import type { Decision, IterationRecord, WaitRecord } from "./types.js";
+
+const iteration = (over: Partial<IterationRecord> = {}): IterationRecord => ({
+  kind: "iteration",
+  n: 1,
+  sessionId: "sess-1",
+  startedAt: 1_000,
+  endedAt: 2_000,
+  turns: 4,
+  ...over,
+});
+
+const input = (over: Partial<ReportInput> = {}): ReportInput => ({
+  runId: "7f3c",
+  status: "stopped",
+  provider: "anthropic",
+  model: "claude-opus-5",
+  usd: 3.84,
+  startedAt: 0,
+  endedAt: 9 * 3_600_000,
+  night: {
+    objective: "reduce the TUI's render cost",
+    branch: "night/reduce-the-tui-render-cost",
+    iterations: 2,
+    commits: ["abc1234def"],
+    waitedMs: 0,
+    fallbackIterations: [],
+    stopReason: "deadline",
+  },
+  records: [iteration({ n: 1, commit: "abc1234def", summary: "cache wrapped lines" })],
+  decisions: [],
+  ...over,
+});
+
+test("the title and headline say what happened without scrolling", () => {
+  const md = renderReport(input());
+  assert.match(md, /^# Night run 7f3c — reduce the TUI's render cost/);
+  assert.match(md, /Stopped: deadline/);
+  assert.match(md, /9h00m/);
+  assert.match(md, /\$3\.84/);
+  assert.match(md, /anthropic\/claude-opus-5/);
+});
+
+test("needs-you comes first, before anything the run achieved", () => {
+  const md = renderReport(
+    input({
+      decisions: [
+        { kind: "needs_human", iteration: 6, at: 1, item: "regenerate golden files?" },
+        { kind: "denied", iteration: 4, at: 1, tool: "bash", rule: "Bash(git commit:*)" },
+        {
+          kind: "decided",
+          iteration: 3,
+          at: 1,
+          question: "memoise where?",
+          choice: "per line",
+          why: "fewer invalidations",
+          reversible: true,
+        },
+      ],
+    }),
+  );
+  assert.ok(
+    md.indexOf("## Needs you") < md.indexOf("## Decisions made for you"),
+    "needs-you must precede decisions",
+  );
+  assert.ok(
+    md.indexOf("## Decisions made for you") < md.indexOf("## Refused actions"),
+  );
+  assert.ok(md.indexOf("## Refused actions") < md.indexOf("## Iterations"));
+  assert.match(md, /regenerate golden files\?/);
+});
+
+test("an empty needs-you section still appears, so its absence is a statement", () => {
+  // A section that vanishes when empty is indistinguishable from one that was
+  // dropped by a bug.
+  const md = renderReport(input());
+  assert.match(md, /## Needs you \(0\)\nNothing is waiting on you\./);
+});
+
+test("irreversible decisions sort above reversible ones", () => {
+  const md = renderReport(
+    input({
+      decisions: [
+        { kind: "decided", iteration: 1, at: 1, question: "q1", choice: "reversible one", why: "", reversible: true },
+        { kind: "decided", iteration: 2, at: 1, question: "q2", choice: "permanent one", why: "", reversible: false },
+      ],
+    }),
+  );
+  // If the reader stops after one line it should be the one they may have to undo.
+  assert.ok(md.indexOf("permanent one") < md.indexOf("reversible one"));
+  assert.match(md, /permanent one — NOT reversible/);
+});
+
+test("a question asked but never answered is shown, not hidden", () => {
+  const md = renderReport(
+    input({
+      decisions: [
+        { kind: "asked", iteration: 9, at: 1, questions: ["drop the legacy theme?"] },
+      ],
+    }),
+  );
+  assert.match(md, /asked "drop the legacy theme\?" — answer not recorded/);
+});
+
+test("an ask the model went on to decide is not reported as unanswered", () => {
+  const decisions: Decision[] = [
+    { kind: "asked", iteration: 3, at: 1, questions: ["memoise where?"] },
+    {
+      kind: "decided",
+      iteration: 3,
+      at: 2,
+      question: "where should memoisation live",
+      choice: "per line",
+      why: "fewer invalidations",
+      reversible: true,
+    },
+  ];
+  const md = renderReport(input({ decisions }));
+  assert.doesNotMatch(md, /answer not recorded/);
+});
+
+test("waits are accounted for — a night can be three commits and eight hours of sleep", () => {
+  const wait: WaitRecord = {
+    kind: "wait",
+    n: 2,
+    from: 0,
+    until: 2 * 3_600_000,
+    reason: "waiting for the anthropic window",
+    provider: "anthropic",
+  };
+  const md = renderReport(
+    input({
+      night: { ...input().night, waitedMs: 2 * 3_600_000 },
+      records: [iteration({ n: 1, commit: "abc1234def" }), wait, iteration({ n: 2, commit: "def5678abc" })],
+    }),
+  );
+  assert.match(md, /waited 2h00m on quota/);
+  assert.match(md, /## Waits \(1\)/);
+  assert.match(md, /⏸ +waited 2h00m/);
+});
+
+test("the iteration list distinguishes committed, failed and notes-only", () => {
+  const md = renderReport(
+    input({
+      records: [
+        iteration({ n: 1, commit: "abc1234def", summary: "cached the tree" }),
+        iteration({ n: 2, failure: "no_finish" }),
+        iteration({ n: 3, summary: "learned the parser is the slow path" }),
+      ],
+    }),
+  );
+  assert.match(md, / 1 ✓ abc1234 {2}cached the tree/);
+  assert.match(md, / 2 ✗ +no_finish/);
+  assert.match(md, / 3 · \(notes\) {2}learned the parser is the slow path/);
+});
+
+test("the review block hands over the exact commands, including how to discard it all", () => {
+  const md = renderReport(input());
+  assert.match(md, /git log --oneline main\.\.night\/reduce-the-tui-render-cost/);
+  assert.match(md, /freecode trace sess-1/);
+  assert.match(md, /git branch -D night\/reduce-the-tui-render-cost/);
+});
+
+test("a run with no --verify says so rather than implying the commits were checked", () => {
+  assert.match(renderReport(input()), /NOT verified \(no --verify\)/);
+  assert.match(
+    renderReport(input({ night: { ...input().night, verifyCommand: "pnpm test" } })),
+    /verified with `pnpm test`/,
+  );
+});
+
+test("an unpriced model reports unknown, never $0", () => {
+  // A zero would read as a free night, which is a different claim entirely.
+  const md = renderReport(input({ usd: undefined }));
+  assert.match(md, /cost unknown \(model not priced\)/);
+  assert.doesNotMatch(md, /\$0\.00/);
+});
+
+test("uncommitted work is called out with why it was left", () => {
+  const md = renderReport(
+    input({ night: { ...input().night, uncommitted: ["src/a.ts", "src/b.ts"] } }),
+  );
+  assert.match(md, /## Uncommitted \(2 paths\)/);
+  assert.match(md, /must never destroy work/);
+  assert.match(md, /- src\/a\.ts/);
+});
+
+test("the same input always renders the same report", () => {
+  // The report is regenerated from the logs after a crash, so a regenerated one
+  // must equal the one the run would have written.
+  const i = input();
+  assert.equal(renderReport(i), renderReport(i));
+});
+
+test("duration reads as a human would say it", () => {
+  assert.equal(duration(0), "0m");
+  assert.equal(duration(90_000), "2m");
+  assert.equal(duration(3_600_000), "1h00m");
+  assert.equal(duration(9 * 3_600_000 + 2 * 60_000), "9h02m");
+  assert.equal(duration(-5), "0m");
+});

diff --git a/apps/core/src/autonomous/report.ts b/apps/core/src/autonomous/report.ts
new file mode 100644
index 00000000..095d2a09
--- /dev/null
+++ b/apps/core/src/autonomous/report.ts
@@ -0,0 +1,253 @@
+// =============================================================================
+// The morning report.
+//
+// PURE fold: manifest + iterations.jsonl + decisions.jsonl → markdown. Nothing
+// here reads a clock, a repo or a network, which is what lets the report be
+// REGENERATED after a crash — the logs are the source of truth, the file is a
+// convenience (`freecode night report <id>`).
+//
+// Order is not cosmetic. It leads with what the user has to act on, then what
+// was decided for them, then what was refused. A report that opens with a
+// commit list is a report that buries the one line that needed a human.
+// Spec: docs/specs/2026-09-28-overnight-runs.md §4.10
+// =============================================================================
+
+import type {
+  Decision,
+  IterationRecord,
+  NightManifestFields,
+  WaitRecord,
+} from "./types.js";
+
+export interface ReportInput {
+  runId: string;
+  night: NightManifestFields;
+  status: string;
+  startedAt?: number;
+  endedAt?: number;
+  provider: string;
+  model?: string;
+  authMode?: "oauth" | "api-key";
+  usd?: number;
+  records: Array<IterationRecord | WaitRecord>;
+  decisions: Decision[];
+  /** `git diff --stat` against the branch point, when the repo could be read. */
+  diffstat?: string;
+  /** Commit subjects keyed by hash, for the iteration list. */
+  subjects?: Record<string, string>;
+}
+
+const isWait = (r: IterationRecord | WaitRecord): r is WaitRecord =>
+  r.kind === "wait";
+
+export function renderReport(input: ReportInput): string {
+  const { night, records, decisions } = input;
+  const iterations = records.filter(
+    (r): r is IterationRecord => !isWait(r),
+  );
+  const waits = records.filter(isWait);
+  const ok = iterations.filter((i) => i.commit).length;
+  const failed = iterations.filter((i) => i.failure).length;
+
+  const out: string[] = [];
+  out.push(`# Night run ${input.runId} — ${night.objective}`);
+  out.push(headline(input, ok, failed));
+  out.push("");
+
+  const needsHuman = decisions.filter(
+    (d): d is Extract<Decision, { kind: "needs_human" }> =>
+      d.kind === "needs_human",
+  );
+  const decided = decisions.filter(
+    (d): d is Extract<Decision, { kind: "decided" }> => d.kind === "decided",
+  );
+  const asked = decisions.filter(
+    (d): d is Extract<Decision, { kind: "asked" }> => d.kind === "asked",
+  );
+  const denied = decisions.filter(
+    (d): d is Extract<Decision, { kind: "denied" }> => d.kind === "denied",
+  );
+
+  // FIRST, always — even when empty, so its absence is a statement rather than
+  // a section that might have been dropped.
+  out.push(`## Needs you (${needsHuman.length})`);
+  if (needsHuman.length === 0) {
+    out.push("Nothing is waiting on you.");
+  } else {
+    for (const d of needsHuman) out.push(`- it.${d.iteration}  ${d.item}`);
+  }
+  out.push("");
+
+  if (decided.length > 0 || asked.length > 0) {
+    out.push(`## Decisions made for you (${decided.length})`);
+    // Irreversible first: if the reader stops after one line, it should be the
+    // one they might have to undo.
+    for (const d of [...decided].sort(
+      (a, b) => Number(a.reversible) - Number(b.reversible),
+    )) {
+      out.push(
+        `- it.${d.iteration}  ${d.choice} — ${
+          d.reversible ? "reversible" : "NOT reversible"
+        }${d.why ? ` — "${d.why}"` : ""}`,
+      );
+    }
+    // A question the model asked and never answered in its report is shown,
+    // never hidden: it is the case where nobody decided anything.
+    for (const a of unansweredAsks(asked, decided)) {
+      out.push(
+        `- it.${a.iteration}  asked "${a.question}" — answer not recorded`,
+      );
+    }
+    out.push("");
+  }
+
+  if (denied.length > 0) {
+    out.push(`## Refused actions (${denied.length})`);
+    for (const d of denied) {
+      out.push(
+        `- it.${d.iteration}  ${d.tool}${d.target ? ` \`${d.target}\`` : ""}  — ${d.rule}`,
+      );
+    }
+    out.push("");
+  }
+
+  if (waits.length > 0) {
+    out.push(`## Waits (${waits.length})`);
+    for (const w of waits) {
+      out.push(
+        `- before it.${w.n}  ${w.provider} — ${duration(w.until - w.from)} (${w.reason})`,
+      );
+    }
+    out.push("");
+  }
+
+  out.push("## Iterations");
+  for (const r of records) {
+    out.push(isWait(r) ? waitLine(r) : iterationLine(r, input.subjects));
+  }
+  out.push("");
+
+  if (input.diffstat?.trim()) {
+    out.push("## Changes");
+    out.push("```");
+    out.push(input.diffstat.trim());
+    out.push("```");
+    out.push("");
+  }
+
+  out.push("## Review");
+  out.push("```sh");
+  out.push(`git log --oneline main..${night.branch}`);
+  out.push(`git diff main...${night.branch} --stat`);
+  const traceable = iterations.find((i) => i.sessionId);
+  if (traceable) {
+    out.push(`freecode trace ${traceable.sessionId}   # any iteration's trace`);
+  }
+  out.push(`git branch -D ${night.branch}   # discard the whole night`);
+  out.push("```");
+
+  if (night.uncommitted?.length) {
+    out.push("");
+    out.push(`## Uncommitted (${night.uncommitted.length} paths)`);
+    out.push(
+      "Left in the working tree on purpose — a forced stop or a crash must never destroy work.",
+    );
+    for (const p of night.uncommitted.slice(0, 40)) out.push(`- ${p}`);
+  }
+
+  return `${out.join("\n")}\n`;
+}
+
+function headline(input: ReportInput, ok: number, failed: number): string {
+  const { night } = input;
+  const parts = [
+    `Stopped: ${night.stopReason ?? input.status}`,
+    // `!== undefined`, not truthiness: a timestamp of 0 is a real value, and
+    // the falsy check silently dropped the elapsed time.
+    input.startedAt !== undefined && input.endedAt !== undefined
+      ? duration(input.endedAt - input.startedAt)
+      : undefined,
+    `${night.iterations} iteration${night.iterations === 1 ? "" : "s"} (${ok} committed, ${failed} failed)`,
+  ].filter(Boolean);
+
+  const cost =
+    input.usd && input.usd > 0
+      ? `$${input.usd.toFixed(2)}`
+      : // Never $0: an unpriced model must stay distinguishable from a free one.
+        "cost unknown (model not priced)";
+  const money = [
+    cost,
+    `${input.provider}${input.model ? `/${input.model}` : ""}${
+      input.authMode ? `, ${input.authMode}` : ""
+    }`,
+    night.waitedMs > 0 ? `waited ${duration(night.waitedMs)} on quota` : undefined,
+    night.fallbackIterations.length > 0
+      ? `${night.fallbackIterations.length} iteration(s) on ${night.fallbackModel ?? "the fallback model"}`
+      : undefined,
+  ].filter(Boolean);
+
+  const branch = [
+    `Branch ${night.branch}`,
+    `${night.commits.length} commit${night.commits.length === 1 ? "" : "s"}`,
+    night.verifyCommand ? `verified with \`${night.verifyCommand}\`` : "NOT verified (no --verify)",
+  ];
+
+  return [parts.join(" · "), money.join(" · "), branch.join(" · ")].join("\n");
+}
+
+function iterationLine(
+  r: IterationRecord,
+  subjects: Record<string, string> | undefined,
+): string {
+  const n = String(r.n).padStart(2);
+  if (r.commit) {
+    const short = r.commit.slice(0, 7);
+    return `${n} ✓ ${short}  ${subjects?.[r.commit] ?? r.summary ?? ""}`;
+  }
+  if (r.failure) {
+    return `${n} ✗          ${r.failure}${r.summary ? ` — ${r.summary}` : ""}`;
+  }
+  // Succeeded with nothing to commit: learnings only.
+  return `${n} · (notes)  ${r.summary ?? ""}`;
+}
+
+function waitLine(w: WaitRecord): string {
+  return `   ⏸          waited ${duration(w.until - w.from)} — ${w.reason}`;
+}
+
+/**
+ * Asks with no decision recorded in the same iteration.
+ *
+ * Deliberately coarse — one ask and one decision in an iteration are paired
+ * without comparing their text, because the model rewords a question when it
+ * answers it. Over-pairing hides nothing; the count is what matters.
+ */
+function unansweredAsks(
+  asked: Array<Extract<Decision, { kind: "asked" }>>,
+  decided: Array<Extract<Decision, { kind: "decided" }>>,
+): Array<{ iteration: number; question: string }> {
+  const answers = new Map<number, number>();
+  for (const d of decided) {
+    answers.set(d.iteration, (answers.get(d.iteration) ?? 0) + 1);
+  }
+  const out: Array<{ iteration: number; question: string }> = [];
+  for (const a of asked) {
+    for (const question of a.questions) {
+      const left = answers.get(a.iteration) ?? 0;
+      if (left > 0) {
+        answers.set(a.iteration, left - 1);
+        continue;
+      }
+      out.push({ iteration: a.iteration, question });
+    }
+  }
+  return out;
+}
+
+export function duration(ms: number): string {
+  if (ms < 0) return "0m";
+  const minutes = Math.round(ms / 60_000);
+  if (minutes < 60) return `${minutes}m`;
+  const hours = Math.floor(minutes / 60);
+  return `${hours}h${String(minutes % 60).padStart(2, "0")}m`;
+}

